-- GENERATED by `wfj generate` from data/quest/quest-0091.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [91208] = { "受け入れる", "DeathknellでFrightened Paladinを見つけてください。", "蘇った同胞のパラディンが皆、我々の新たな現実にすぐ馴染めるわけではありません。自分たちが今や、ある意味で、生涯をかけて戦ってきたものそのものになったという事実を受け入れられずに苦しむ者もいます。\n\nそうした者たちは、多くの場合、優しい態度と、共感して耳を傾けてくれる相手を必要としているだけです。残念ながら、すぐに暴力に走る者も多いのです。この礼拝堂のすぐ西の丘へ逃げ込んだ、怯えたパラディンを見つけてください。友情の手を差し伸べてください。できるなら、その者を光のもとへ連れ戻してあげてください。", nil, "悲しいことに、蘇った後で同じような狂気に屈してしまう兄弟姉妹は少なくありません。Forsakenの魂はどれも尊いものですが、順応できない者にはきれいな最期を与えることが、私たちにできる最善の場合もあるのです。\n\n彼女のために光へ祈りを捧げましょう。為すべきことを為してくれてありがとう、{name}。", 0x369056a8, 0x4e575d59, 0xf3aba797, nil, 0x08cfc7d1, "...m." },
  [91209] = { "訓練の続き", "Deathknellから東へ道をたどり、Brillの町を見つけてください。訓練を続けるため、Shari Stilwellに報告してください。", "Lordaeronはかつての姿ではないかもしれませんが、我らの故郷は今もあらゆる脅威から守られる必要があります。あなたが外の世界へ出て向き合う時が来ました。次の行き先はTirisfal Glades中央のBrillの町です。そこでShari Stilwellに会ってください。彼女があなたの訓練の続きを見てくれるでしょう。\n\n出発する前に最後の助言を――Forsakenの地を旅するパラディンとして、十分に気をつけてください。Dark Ladyに仕える者の中には、我々と、我々が光に近いことを疑う者が大勢いるのです。", nil, "よく来たな、{class}。我らの仲間がこの地をさらに歩き回っているのを見るのは、いつも心強いものだ。ここBrillには、君のような冒険者の助けを必要としている者が大勢いる。仕事を探し、光の中で強くなるといい。訓練が必要なときはいつでも私のところへ戻ってこい。\n\n君が私とBrillの人々に力を示したら、次の旅路への導きを授けよう。\n\n光と共に行け、{class}。", 0x4085cde1, 0x85d93d6b, 0xaa599bfa, nil, 0x5e8d646c, "...m." },
  [91282] = { "第二の故郷", "Bandarion Keepの砦を見つけ、そこにいるBreton Samuelsに報告してください。", "蘇った兄弟姉妹たちがあなたのように力をつけていく姿を見るのは心強いことです。しかし、真に持てる力を発揮できるのは、共同体と信仰の共有があってこそです。そのために、我々はここTirisfalで新たなパラディンの騎士団を結成し始めました。\n\nもっと知りたいなら、Northface Rockにある我々の修道院を訪ねるとよいでしょう。Bandarion Keepという名です。Solliden Farmsteadのすぐ北西の断崖の上にあるので、見逃すことはないはずです。", nil, "また新兵か？Tyr's Watchへようこそ、兄弟。", 0x323b0ccf, 0x66582164, 0xe91ac1c9, nil, 0xed54e9da, "...m." },
  [91285] = { "門に迫るMurloc", "Vile Fin Attackerを$N1体とVile Fin Seerを$N2体倒し、終わったらBreton Samuelsに報告してください。", "普段なら新入りにもう少しもてなしをするんだが、今はちょっとmurlocの問題を抱えていてね。\n\nmurlocの一族がかつてこの砦を産卵場にしていたんだ。俺たちが移ってきて追い出して以来ずっと厄介だったが、最近は手に負えなくなってきている。君は場数を踏んできたように見える。この害獣どもを追い払うのを手伝ってくれないか？ 東へ続く道沿いの断崖や、西の湖の周りの野営地に潜んでいるはずだ。", nil, "助かったよ。これで襲撃が完全に止まるとは思わないが、少しは勢いが弱まるといいんだがな。槍で背中を刺そうとしてくるmurlocがいなくたって、ここを再建するのは十分大変なんだ。", 0x7785ffc2, 0x7b21c67e, 0x12268215, nil, 0x273fdfba, "...m." },
  [91294] = { "敷地を巡る", "Bandarion Keepの住人たちと話してください。", "murlocの襲撃という差し迫った脅威は収まったから、我々の拠点を見て回るといい。まだ大したものじゃないが、ここが我が家だ。\n\n見て回ったら、我々のリーダーのDanitha Morrを訪ねてくれ。彼女が落ち着けるよう手を貸してくれるだろう。\n\n会えて本当に嬉しかったよ、{name}。光が君を導かんことを。", nil, "Bretonに言われてここまで来たのか。いいぞ。\n\n私はDanitha Morr。この砦で司令官と呼べるものに一番近い立場にある。今なお光への忠誠を守る者たちとの仲間を求めて来たのなら、正しい場所に来たな。\n\n我々がここにしっかりと根を下ろすには、まだやるべきことが山ほどある。手を貸してくれるなら、大いに感謝するよ。", 0x2887ca72, 0x410e846c, 0x44585301, nil, 0x902d5c25, "...m." },
  [91316] = { "修理", "Tirisfal GladesのShadowvaleでSturdy Lumberを12個集めてください。", "Undercityからこれほど離れていると補給が難しく、この砦を修復するのに必要な建材がひどく不足している。その件で君の手を借りたい。\n\n廃墟となったShadowvaleの村は、ここから南西のWhispering Forestにある。建物の一つに、あらゆる物をしまっておく古い地下貯蔵庫がある。そこなら使える資材があるだろう。集められるだけ集めて戻ってきてくれ。", "場所こそすべて、と言われている。この断崖の上にそびえる要塞は堂々として見えるかもしれないが、まともな文明からこれほど離れていては、補給を保つのがかなりの難題になっている。我々の不運な見落としだ。", "Shadowvaleへの旅が実を結んだようで何よりだ。後でBretonとほかの新兵を何人か送って、地下室の残りを片付けさせ、暗闇の中に残ったものを回収させよう。", 0x2cfcd9f0, 0xb8282c24, 0x1518690b, 0xf3019911, 0xdf7b4d57, "....." },
  [91317] = { "Tarnished", "Tirisfal GladesでTarnished Drudgeを8体、Tarnished Zealotを6体倒し、Commander Rudolph Gelhardtの首を手に入れてください。", "君もすでに目にしたかもしれないが、蘇ったパラディンの皆が新たな存在にうまく馴染めたわけではない。生前の偏見を持ち越し、同胞のForsakenに暴力を振るい続ける者もいる。\n\n現状、我々は同胞から信用されていない。彼らは、生者が光の名のもとに加えた迫害をよく覚えているからだ。そしてこうした襲撃はそれを悪化させるだけだ。こうした堕ちた者たちの一団が、南西のShadowvaleに住み着いている。奴らを始末し、その首領の首を持ってきてくれ。", "Tarnishedは、我々が他のForsakenとの間にわずかに持つ善意さえ脅かしている。かつての兄弟姉妹と刃を交えるのは心苦しいが、生まれたばかりの我らの団が生き延びるためには、奴らを止めねばならない。", "見事だ、{name}。Tarnishedの連中がForsakenを襲って殺すたびに、我々を非難する者たちがパラディンへの不信をあおるのがそれだけ容易になる。奴らを排除すれば、我々の大義を推し進め、ここTirisfalでの居場所を固めることにつながるだろう。\n\nForsakenとHordeに完全に受け入れられるまでには、長い時間がかかるかもしれない。何年も……いや、何十年もかかるかもしれないが、我々にできる最善は、自分たちの価値を示そうと努力し続けることだ。", 0x56e9442f, 0x783dab34, 0x72df7fd8, 0x41fb5732, 0x6fd3aac2, "....." },
  [91723] = { "繊細な計器", "Jasperlode MineでKobold Geomancerを8体倒し、Tower of AzoraにいるHamish Bergwortのところへ戻ってください。", "ええい、忌々しい！ この繊細な秘術の計器を調整しようとするたびに、エネルギーの奔流でまた狂わされてしまう。\nその奔流は北から来ているようだ。あの原始的なKoboldsが粗雑な魔法の練習をしている所だ。私が研究を続けられるよう、奴らを何匹か片付けてくれないか？", nil, "よくやってくれた、友よ。もう一度調整を試してみよう……", 0x7065a8eb, 0xe5f80ea7, 0x91c5f081, nil, 0x8dec828f, "...m." },
  [91724] = { "繊細な計器", "Stone Cairn LakeでDefias Rogue Wizardを6体倒し、Tower of AzoraにいるHamish Bergwortのところへ戻ってください。", "あと少しで……なんと、Netherにかけて！ まだ何かが計器を乱している。\n実に苛立たしいよ、{name}。地元の山賊どもがStone Cairn Lakeの近くで呪文の練習をしているという噂を聞いた。奴らを止めれば、この乱れもようやく収まって、研究が進むかもしれないな？", nil, "すべて正常に動いているようだ。ありがとう、{name}。", 0x7065a8eb, 0xb6e0db48, 0xe7761ff1, nil, 0x4af97dcf, "...m." },
  [91725] = { "Stolen Enchanting Supplies", "Stone Cairn Lake周辺のgnollのキャンプからStolen Enchanting Suppliesを5個集め、Tower of Azoraの近くにいるBlixie Fitzwinkのところへ戻ってください。", "Master Theocritusに言われて交易所までenchanting suppliesを受け取りに行ったんですが、帰り道でgnollの群れに襲われてしまったんです！\n\n荷物を落として逃げてきましたが、持たずに帰ったら、罰として何週間もpolymorphの実験の後片付けをさせられてしまいます！ 代わりに見つけてきてもらえませんか？", "物資は見つかったか？", "ああ、ほっとした！全部そろっているみたい。ありがとう！", 0x78bd98c1, 0xeda8b676, 0xd9d3fe8f, 0x3a2cb041, 0x3db19b3c, "....." },
  [91732] = { "良質な鋼", "Jasperlode MineからMining Toolsを4個集め、Eastvale Logging CampにいるHagar Loweのところへ戻ってください。", "戦争のあと良質な鋼は不足していて、我々の道具もそのせいで傷んでいる。Jasperlodeの鉱夫たちは精巧に作られたツルハシを使っていた。その一部はまだ鉱山の奥に残っているだろう。いくつか取ってきてくれないか。その鋼を再利用できるか試してみよう。", "もう鉱山へは行ってきたか？", "おお、いいね。この輝きが見えるかい？まったく、昔のようなものはもう作られていないよ。", 0x72aed2a2, 0xd649abdf, 0x8701f873, 0xbc85eca8, 0x47745ccb, "....." },
  [91733] = { "下流へ", "Eastvale Logging Campから下流へ流されたWaterlogged Axe、Waterlogged Saw、Waterlogged Toolboxを集め、Ormin Pelfordのところへ戻ってください。", "交易所から補給品を運んで帰る途中、荷馬車がひっくり返って、補給品が川に落ちてしまったんだ！ 捕まえる前に、もう下流へ流されてしまった。\nあそこにはmurlocや狼がいるから、僕一人じゃ取り戻せる見込みはない。君はたくましそうだね。見つけてきてくれないか？", "物資は見つかったか？", "少し濡れているようだね、{name}。すまなかった。でも、補給品を取ってきてくれてありがとう。", 0x5377b6c2, 0x4104ac2d, 0xf5998821, 0x3a2cb041, 0xc2d835d9, "....." },
  [91736] = { "Applejackの蒸留器", nil, nil, "装置を調べると、強いリンゴの香りが鼻を刺す。", nil, 0xdf027785, nil, nil, 0x90ed44dc, nil, ".mm.m" },
  [91738] = { "リンゴのごちそう", nil, nil, nil, nil, 0xc00668c0, nil, nil, nil, nil, ".mmmm" },
  [91740] = { "Croaky's Head", "Croaky's HeadをRidgepoint TowerにいるMerell Rossに届けてください。", "このmurlocは間違いなく、しばらくの間このあたりの道を脅かしていたのだろう。近くの見張りの衛兵たちはその死を知りたがるに違いない。", "何か？", "先週、murlocのせいで見張りの仲間を2人失ったんだ、{class}。奴らの指導者が倒れた今、Elwynnから追い出し始められるといいんだが。", 0x9a2d8e95, 0xfefeb249, 0x70acafd1, 0x0c07a888, 0x8d54c4b8, "....." },
  [91741] = { "Nibbled-On Book", "本をBrother Paxtonに返してください。", "<koboldの一匹がこの本を落とした。koboldが食べようとしたようだ。\n\n修道院の中のBrother Paxtonが小さな図書室を管理している。本はそこから来たに違いない。>", "そこに持っているのは何だい？私の本のひとつみたいだが。", "ちょっと！どうしてそれを持ってるんだい？棚にあるはずなのに！ああ、まいった、またkoboldに本を盗まれたんだ。きっと食べたいんだろう！\n\n本を持ち帰ってくれてありがとう。でも、なくなったほかの蔵書はどうしたらいいんだろう？", 0xdc36fd8f, 0x60fd6d4c, 0x926272a4, 0xb5ada1fe, 0xbe3f5ca7, "....." },
  [91743] = { "いたずらなネズミども", "Northshire ValleyのkoboldからStolen Bookを$N1冊取り戻し、Brother Paxtonに返してください。", "あのひどいkoboldどもが私の本を食べているんです！ 私の図書室を丸ごと平らげてしまう前に、取り戻してください。", "私の本はもう救い出してくれたかい、{name}？！", "本当にありがとう！ほら！このハウツー本を1冊持っていって。私には必要ないから。\n\nでも、まだたくさんの本がなくなってる。koboldは本を食べてはいないみたいだ。じゃあ、どうして欲しがるんだろう？", 0x5ecfe128, 0xca0dec56, 0x36c2ff3a, 0x9e3c12c9, 0xcb496646, "....." },
  [91745] = { "Miningの相談役", "Northshire ValleyのEcho Ridge Mineの外にいるKelsey Fargoと話してください。", "新しい採掘見習いのKelsey Fargoと話してきてくれ。彼女は鉱山のすぐ外で働いていて、koboldどもが何をしているか見ているはずだ。ついでに採掘について少し教えてもらえるかもしれないな。", nil, "本を持ったkobold？ああ、koboldが本を抱えて行ったり来たりしながら、互いにわめき合ってるのを見たよ。きっと修道院の中の図書館から盗んでるんだろう。", 0x70de9b61, 0x928069a0, 0x595703ec, nil, 0x968f291e, "...m." },
  [91746] = { "Elmpaw's Head", "Elmpaw's HeadをGoldshireの近くにいるHelene Peltskinnerに届けてください。", "この戦利品は、Elmpawに対するあなたの勝利を見事に思い出させてくれる。地元のハンターや皮はぎ職人なら、その話を聞きたがるかもしれない。", "何か？", "それじゃあ、Elmpawを仕留めたのか？大したものだ、{name}！\n\nその戦利品のお返しに何か渡そう。私が剥製にしたら、これを炉棚に飾るために大金を払うコレクターを何人か知っているんだ。", 0x6c96dddb, 0xa7c38435, 0x2ae37dbd, 0x0c07a888, 0xd51955d8, "....." },
  [91751] = { "Rough Wolf Pelts", "Elwynn Forest周辺の狼の皮をはいでRough Wolf Peltを7枚手に入れ、Goldshireの近くにいるHelene Peltskinnerに届けてください。", "Skinningの練習の機会を探しているの？ 夫はいつも狼狩りを手伝ってくれるんだけど、今は修道院のほうで忙しくて。受けている注文を仕上げるのに、毛皮をもっと集める手伝いがほしいのよ。", "狼の毛皮は手に入ったか？", "毛皮をよく集めてくれた、{class}。君には狩りの本物の才能があるな。", 0xe1344efa, 0x7a609a25, 0x993378eb, 0xc1490377, 0x024aeaa4, "....." },
  [91752] = { "全体像", "Shinyfinder NarfからSack of \"Picture\" Booksを取り戻してください。その袋をNorthshire's Abbeyのすぐ中にいるMarshal McBrideのところへ持って行ってください。", "時々、koboldが「Narfに絵を！」って叫びながら通っていくんだ。Narfが誰かは知らない。鉱山の奥にいるkoboldの親玉の一匹かな？ きっと今頃は本を袋いっぱい持ってるよ。\n\nその本を取ってきて、ここの保安官、Marshal McBrideに届けて。友達を連れていったほうがいい。鉱山の中のkoboldはずっと凶暴だから。", "盗まれた本はもう取り戻したか？", "盗まれた本を返してくれてありがとう、{name}。すぐにBrother Paxtonへ届けるよ。\n\n君はこのあたりでなかなかの英雄になりつつあるね。よくやった！", 0xf0a9a4ae, 0x0274d4d1, 0x64d74190, 0x98bda539, 0x3c4f5b85, "....." },
  [91753] = { "Enchantingの手ほどき", "Tower of AzoraにいるKitta Firewindは、Luminous Residueを3個集めてほしいと言っています。\n\nLuminous Residueは、Kobold Geomancerが落とすCrude Wax Effigiesを分解すると手に入ります。", "学問的な厳密さはもちろん付呪師の技に欠かせないが、実践的な基礎も大いに役立つものだ。例として、卑しいKoboldを考えてみたまえ。正式な教育を受けていないにもかかわらず、奴らは簡単な呪文や付呪に生来の素質のようなものを示す。\n\n奴らの蝋人形をいくつか手に入れ、その中に込められた付呪を分解してみたまえ。得るところがあるかもしれん。", "あなたの研究で何が明らかになりましたか？", "理論と実践はコインの表と裏だ、{name}。覚えておくといい。", 0x775e64ad, 0x5706d360, 0x77774694, 0xcd72ab2a, 0x3bbdc1ae, "....." },
  [91758] = { "あのKoboldを追え！", "Northshire's Abbeyの裏の厩舎の近くにいるTordrin Sternbladeと話してください。", "koboldの件はまだ終わっていないぞ。Kelseyから、koboldが本の詰まった大きな袋を持って鉱山を出ていったと知らせがあった。Brother Paxtonのために本を取り戻せるよう、そのkoboldを追跡してほしい。\n\nTordrin Sternbladeと話してくれ。Ironforgeから来たばかりの新しいハンターのトレーナーだ。修道院の裏、厩舎の近くにいる。このkoboldの泥棒を追跡する手助けをしてくれるだろう。", nil, "この害獣を追うのを手伝ってやるよ。ちょいと何か作ってやろう。", 0x5b4c7f86, 0xba85d0f1, 0xbabf3db2, nil, 0x0f74c33b, "...m." },
  [91772] = { "しーっ！ Koboldsを狩ってるんだ", "koboldの足跡をたどり、わかったことを報告してKobold Tracking Kitを渡しに、GoldshireにいるMarshal Dughanのところへ行ってください。", "よし。このkobold tracking kitを持っていけ。Marshal McBrideが気にしているkoboldを追跡できるはずだ。\n\n足跡をたどって、見つけたものをGoldshireのMarshal Dughanに届けてくれ。\n\nこの害獣どもはNorthshireの外で何か企んでいる気がする。だからDughanの助けが要るだろう。", "Koboldsがどこへ向かっているか、分かったか？", "これは何だ、{name}？koboldを追跡しているのか？\n\nまあ、もちろん奴らはFargodeepの鉱山へ向かっているさ！あそこはkoboldだらけだからな。\n\nよくやった、と言うべきかな。誰かにその問題を片付けてもらう必要があるな。", 0xccca4f37, 0x4c6f788d, 0x88b384bf, 0x76315b25, 0x94488fef, "....." },
  [91775] = { "本の返却", "Lost Bookを6冊と\"Fun with Elementals\"を見つけ、Marshal Dughanに返してください。", "Fargodeep Mineを調べるついでに、Brother Paxtonの本が見つかったら返してやってくれ。特にPaxtonは「Fun with Elementals」という題の本をとても心配している。koboldでもそれを使って精霊の召使いを呼び出せると考えているんだ。気をつけろ、鉱山の奥はかなり危険だ。仲間を連れていったほうがいい。\n\n見つけた本を守るため、この本袋を持っていけ！", "もう本は全部見つかったか？", "その熱心さには感服したよ、{name}。Brother Paxtonが本の一覧を送ってくれたんだが、なくなった本のほとんどを君が見つけてくれた。残りはJasperlode Mineへ持ち去られたに違いない。\n\nその本の袋は持っていっていいよ！", 0xd01af3bc, 0x88f1a8d6, 0xf4a33e50, 0x546df3d0, 0xb1a94cf2, "....." },
  [91777] = { "希少本", "\"Geomancy for Curious Young Wizards\"と\"Arcane Explainer: Magical Stuff in Simple Words\"を取り戻し、Northshire's Abbeyの中にいるBrother Paxtonに返してください。", "Brother Paxtonのリストで見つかっていない本は、あと2冊だけです。「Geomancy for Curious Young Wizards」と「Arcane Explainer: Magical Stuff in Simple Words」です。\n\nkoboldたちがJasperlode Mineへ持ち去ったに違いありません。どうかその2冊の本を探し出して、Brother Paxtonのもとへ持ち帰ってください。\n\nただ、かなり危険なことになりそうです。「見習い」のkoboldがエレメンタルを召喚していたのなら、親方が何をしでかすか分かったものではありません。私があなたなら、仲間を何人か連れて行きますね。", "なくなった私の本は、もう全部見つかったかい？", "ああ、{name}！私の図書館を救ってくれて本当にありがとう。とても大きな恩ができたよ。この立派な武器を1つ受け取ってほしい。民兵団に回すつもりだったけど、君のほうがうまく使えるだろう。", 0xa9c579cb, 0xa02ab9c4, 0xa51f628c, 0xf4232bfe, 0xb2abd943, "....." },
  [91858] = { "外交問題", "Silverpine ForestのThe Sepulcherへ行き、行方不明のEarthen Ringの旅人たちについてTrevan Rolと話してください。", "Silverpineでの実に不運な出来事が、hordeの目に我々の価値を示す絶好の機会をもたらした。\n\nEarthen Ringの使節二人が、Tarren Millへ向かう途中Silverpine Forestで行方不明になった。それ以上のことはほとんど分かっていないが、噂ではかなりの外交問題になりつつあるらしい。行方不明者を取り戻せれば、我々が切実に必要としている正当性を得る助けになるだろう。\n\nThe Sepulcherに我々の者、Trevan Rolがいる。そこへ行って彼と話してくれ。", nil, "Danithaに言われて来たのか？それなら、君がここにいる理由はもう分かっている。とんでもない厄介ごとに足を踏み入れたな、{class}。", 0x860aa6df, 0x49857281, 0x51cda335, nil, 0xe436fee9, "...m." },
  [91859] = { "奇妙な二人組", "最近The Sepulcherを通っていった謎のEarthen Ringの旅人たちについて、Deathguard Baldrenと話してください。", "単刀直入に言おう、この「使節」はただの外交官じゃない。一人はトーレンだった。Earthen Ringならよくあることだが、もう一人は――信じられないだろうが――elfだった。*high* elfだ。二人ともマントで身を隠していたが、俺はquel'doreiを見たことがあるし、大事な小指を賭けてもいい、あれはそうだった。\n\nなぜelfがトーレンに同行してhordeの領土を通っていたのか？ さあな、俺にも分からん。俺が知っているのはそこまでだ。町の入口近くにいるDeathguard Baldrenと話すといい。", nil, "お前たちパラディンは好きになれんが、タイミングだけは申し分ないと言っておこう。腕より運、ということかな？", 0x81390067, 0x9840d880, 0x5b66726d, nil, 0x4666daba, "...m." },
  [91860] = { "過酷な運命", "東にあるFenris Isleを調べ、Earthen Ringの旅の一行がどうなったのか突き止めてください。", "昨夜パトロールに出ていたとき、gnollの一団がFenris Isleの岸辺で、ひどく大きな死体を火葬の薪の山に投げ込んでいるのを見かけた。エルフも、もっと小さな死体も見当たらなかったが、そいつらにとって良い兆しとは言えないだろうな。\n\n勇敢か馬鹿なら、Fenris Isleに突撃してもっと調べてくるのは勝手だ。だが俺に言わせれば、どうせとっくに死んでいるお高くとまったエルフ一人を探すには、手間がかかりすぎる。\n\nお前たちパラディンが誓いを立てたり、見込みのない大義を背負い込んだりするのが好きなのは知っているが、こいつはその価値がない。信じろ。", nil, "<目の前の死体は間違いなくトーレンのもので、火葬台に放り込まれる前にひどくかじられていたことが分かる。だが、聞かされていたエルフの女性の痕跡はない。もしかすると、彼女はまだ近くの砦の奥深くのどこかで生きているのだろうか？\n\n危険だろうが、確かめる方法は1つしかない。>", 0x08dbafc9, 0x269e6b75, 0x06c5da17, nil, 0x0c72db2b, "...m." },
  [91861] = { "Fenris Keepへ", "北にあるFenris Keepを調べ、Earthen Ringの一行の行方不明者を探してください。", "<死体が一つしか見つからなかったのは、希望の持てる兆しだ。TrevanとHadrecが話していたHigh Elfは、もしかすると近くの砦のもっと奥のどこかで、まだ生きているのではないだろうか？>", nil, "あなたはForsakenの者ですね？私を自由にしてくれませんか？\n\n私にはもう時間がないのです。どうか急いでください！", 0x52a5ca6c, 0x05375492, 0xfcb8e7e8, nil, 0xc4755d7d, "...m." },
  [91862] = { "Lumina Windsinger", "Rot Hide GnollからFenris Isle Keyを取り戻し、それを使ってLumina Windsingerを解放してください。", "Quel'dorei？ いいえ、私は「quel'dorei」ではありません。私はLumina Windsinger、shen'doreiです。Windshaper Skyborneの一人です。\n\n私はEarthen Ringの客人としてこの地に来ました。仲間のBanonと私は、Arathi Highlandsへ向かうためにSilverpineを通っていました。そこで精霊の合流点を調べるためです。見ての通り、たどり着けませんでしたが。\n\nでも今はそんな話をしている時間はありません。近くのgnollを倒してください。この檻の鍵を取り戻して、私を解放してください。安全な所まで逃げたら、残りをお話しします。", "Gnollsは、私がこれまでAzerothで出会った中で二番目にひどい生き物だ。", "ありがとう、{class}。残念ながら、まだ危険から抜け出せたわけではない。", 0x8615ca23, 0x9d3e70b4, 0x1c33efa2, 0xd342e852, 0x59d83bf0, "....." },
  [91899] = { "Sealed Crate", nil, nil, "また配達か！すばらしい。そこの山のそばに置いてくれ、報酬の話をしよう。", "よく働いてくれてありがとう、{name}。最近、交易路を襲う山賊や盗賊が増えているんだ。ほかにもその辺に転がっている木箱を見つけたら、ここへ持ってきてくれ。あとはこちらで対処する。\n\nこれが報酬だ。", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91900] = { "Sealed Crate", nil, nil, "また配達か！すばらしい。そこの山のそばに置いてくれ、報酬の話をしよう。", "よく働いてくれてありがとう、{name}。最近、交易路を襲う山賊や盗賊が増えているんだ。ほかにもその辺に転がっている木箱を見つけたら、ここへ持ってきてくれ。あとはこちらで対処する。\n\nこれが報酬だ。", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91901] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91904] = { "Sealed Crate", nil, nil, "また配達か！すばらしい。そこの山のそばに置いてくれ、報酬の話をしよう。", "よく働いてくれてありがとう、{name}。最近、交易路を襲う山賊や盗賊が増えているんだ。ほかにもその辺に転がっている木箱を見つけたら、ここへ持ってきてくれ。あとはこちらで対処する。\n\nこれが報酬だ。", 0xfc2b137e, nil, nil, 0x5e066350, 0x3a3beeaf, ".mm.." },
  [91905] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91906] = { "Sealed Crate", nil, nil, nil, nil, 0xfc2b137e, nil, nil, nil, nil, ".mmmm" },
  [91920] = { "野生の目", "murlocの目を3個集め、SepulcherにいるApothecary Renferrelのところへ持って行ってください。", "Apothecary Renferrelの調合の効果を疑うつもりはないが、あの薬に目立った違いがあったと言えば嘘になる。\n\nLake Lordamereの岸辺にはmurlocがうじゃうじゃいる。そして注目すべきことに、murlocには目がある。薬剤師殿の新しいことへの意欲は、最近の心臓への執着で抑え込まれているのだろう。彼にいくつか持っていってやってくれ。\n\nいずれ二度目の死を迎えるか、やり方を疑ったせいでRenferrelに殺されるかを選ぶなら、私は後者を選ぶ。", "ああ。戻ったのか？", "薬が効かなかった？当然だ、効くはずがない。お前が持ってきた心臓は足りなかった。レシピにははっきり6個と書いてある。お前が持ってきたのは3個だ。\n\nもっとも、murlocの部位の使い道は今まで考えたこともなかったが……\n\n<Renferrelは目玉を受け取る。>\n\nお前のDeathstalkerの力を取り戻すためなら、私の手持ちの心臓を少しくらい犠牲にしても構わん。", 0x44275ed7, 0xd4c23f40, 0x9795c646, 0x45e80936, 0x10bbdd28, "....." },
  [91921] = { "Quinnのもとへ（再び）", "Quinnの薬を、Sepulcherの北のIvar PatchにいるQuinn Yorickのところへ持って行ってください。", "これがQuinnの回復を助ける新しい薬だ。心臓丸ごと6つから抽出した愛情で作ってある。\n\nさて、君がいるとまた書類仕事が増えるので、失礼させてもらうよ。", "戻ってきたか！グールに成り果てることを受け入れかけていたところだ。", "<Quinnは薬を受け取って飲み干す。>\n\nああ、効いているのが分かる。すぐにまた旅ができるようになるだろう。\n\n大きな恩ができたよ、{name}。", 0x641834db, 0xed042c3f, 0x0c746cd7, 0x1411f25f, 0xc5dd8287, "....." },
})
